def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive = []
    prev_bids = []
    urgent_opp = 0
    rich_opp = 0
    for opp in opponents_status.values():
        if opp.get('alive'):
            alive.append(opp)
            if opp.get('budget', 0) >= DAILY_SALARY * 1.2:
                rich_opp += 1
            if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
                urgent_opp += 1
            prev = opp.get('previous_trace', {}) or {}
            bid = prev.get('bid')
            if bid is not None:
                prev_bids.append(bid)

    if not alive:
        return max(0, min(budget, round(DAILY_SALARY * 0.35, 2)))

    players = len(alive) + 1
    scarcity = players * WATER_REQ - supply
    base = DAILY_SALARY * 0.45

    if scarcity > 20:
        base = DAILY_SALARY * 0.9
    elif scarcity > 10:
        base = DAILY_SALARY * 0.75
    elif scarcity > 0:
        base = DAILY_SALARY * 0.62
    else:
        base = DAILY_SALARY * 0.42

    if prev_bids:
        max_prev = max(prev_bids)
        avg_prev = sum(prev_bids) / len(prev_bids)
        if max_prev >= DAILY_SALARY * 0.9:
            if hp <= 3 or no_water >= 1:
                base = max(base, DAILY_SALARY * 0.94)
            else:
                base = min(base, DAILY_SALARY * 0.38)
        else:
            pressure_bid = max_prev + 1.25
            if avg_prev < DAILY_SALARY * 0.45:
                pressure_bid = max(pressure_bid, DAILY_SALARY * 0.5)
            base = max(base, pressure_bid)

    if hp <= 2:
        base = max(base, DAILY_SALARY * 0.97)
    elif hp <= 4:
        base = max(base, DAILY_SALARY * 0.82)

    if no_water >= 2:
        base = max(base, DAILY_SALARY * 0.99)
    elif no_water >= 1:
        base = max(base, DAILY_SALARY * 0.88)

    if urgent_opp >= max(1, len(alive) // 2):
        base += 3.0
    if rich_opp >= max(1, len(alive) // 2):
        base += 2.0

    days_left = max(1, 10 - day_context['day'] + 1)
    reserve_target = days_left * DAILY_SALARY * 0.42
    if budget < reserve_target:
        base *= 0.88
    if budget < DAILY_SALARY * 1.2 and not (hp <= 3 or no_water >= 1):
        base *= 0.8

    if supply >= MAX_SUPPLY - 1 and hp > 4 and no_water == 0:
        base = min(base, DAILY_SALARY * 0.48)
    if supply <= MIN_SUPPLY + 1:
        base = max(base, DAILY_SALARY * 0.72)

    bid = max(0.0, min(budget, base))
    return round(bid, 2)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append((opp_id, opp))

    if not alive_opps:
        return min(float(my_status['budget']), DAILY_SALARY * 0.4)

    # Immediate reaction to yesterday's bids (only previous_trace)
    prev_bids = []
    prev_hp_after = []
    for _, opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass
        hp_after = prev.get('hp_after', None)
        if hp_after is not None:
            try:
                prev_hp_after.append(float(hp_after))
            except Exception:
                pass

    my_hp = float(my_status['hp'])
    my_budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    # Estimate how desperate we should be
    desperation = 0.0
    if my_hp <= 2.0:
        desperation = 1.0
    elif my_hp <= 4.0:
        desperation = 0.7
    elif no_water_days >= 2:
        desperation = 0.6

    # If opponents were bidding aggressively yesterday, we increase to avoid losing allocation.
    if prev_bids:
        highest_prev_bid = max(prev_bids)
        second_highest = sorted(prev_bids)[-2] if len(prev_bids) >= 2 else highest_prev_bid

        # Aggressive threshold tuned to DAILY_SALARY scale
        aggressive = highest_prev_bid >= DAILY_SALARY * 0.85
        if aggressive:
            # If we are healthy, don't fully mirror; if low HP, mirror more.
            base = DAILY_SALARY * (0.35 if my_hp > 4.0 else 0.9)
            # Nudge above second-highest to secure water when possible
            target = max(base, second_highest + 1.5)
        else:
            # Moderate bid: slightly above highest_prev_bid when close, else stay efficient.
            target = max(DAILY_SALARY * 0.5, highest_prev_bid + (2.0 if highest_prev_bid >= DAILY_SALARY * 0.55 else 0.0))

    else:
        # No bid info: use our own state and supply pressure.
        supply_pressure = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY + 1e-9)
        # Higher supply => lower bid
        target = DAILY_SALARY * (0.65 - 0.25 * supply_pressure)

    # Convert target into a safe budget-constrained bid
    # Also avoid spending too much when not desperate.
    if desperation <= 0.0:
        cap = DAILY_SALARY * 0.65
    elif desperation < 0.8:
        cap = DAILY_SALARY * 0.85
    else:
        cap = DAILY_SALARY * 0.98

    bid = min(my_budget, min(target, cap))

    # Ensure non-trivial bid
    min_bid = DAILY_SALARY * 0.25
    if bid < min_bid:
        bid = min(my_budget, min_bid)

    # Final clamp
    if bid < 0.0:
        bid = 0.0
    return float(bid)
